ay_name": "Proceedings of the IEEE", "issn_l": "0018-9219", "issn": ["0018-9219", "1558-2256"], "is_oa": false, "is_in_doaj": false, "is_core": true, "listed_in": ["anvur-scientific", "ccf-a", "cwts-core", "dongbi-b", "jufo-3", "norway-2", "poland-200", "russia-white-list-1", "vabb-shw"], "host_organization": "https://openalex.org/P4310319808", "host_organization_name": "Institute of Electrical and Electronics Engineers", "host_organization_lineage": ["https://openalex.org/P4310319808"], "host_organization_lineage_names": ["Institute of Electrical and Electronics Engineers"], "type": "journal"}, "license": null, "license_id": null, "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "Proceedings of the IEEE", "raw_type": "journal-article"}, "abstract": "Inspired by nature, molecular communications (MC), i.e., the use of molecules to encode, transmit, and receive information, stands as the most promising communication paradigm to realize the nanonetworks. Even though there has been extensive theoretical research toward nanoscale MC, there are no examples of implemented nanoscale MC networks. The main reason for this lies in the peculiarities of nanoscale physics, challenges in nanoscale fabrication, and highly stochastic nature of the biochemical domain of envisioned nanonetwork applications. This mandates developing novel device architectures and communication methods compatible with MC constraints. To that end, various transmitter and receiver designs for MC have been proposed in the literature together with numerable modulation, coding, and detection techniques. However, these works fall into domains of a very wide spectrum of disciplines, including, but not limited to, information and communication theory, quantum physics, materials science, nanofabrication, physiology, and synthetic biology. Therefore, we believe it is imperative for the progress of the field that an organized exposition of cumulative knowledge on the subject matter can be compiled. Thus, to fill this gap, in this comprehensive survey, we review the existing literature on transmitter and receiver architectures toward realizing MC among nanomaterial-based nanomachines and/or biological entities and provide a complete overview of modulation, coding, and detection techniques employed for MC. Moreover, we identify the most significant shortcomings and challenges in all these research areas and propose potential solutions to overcome some of them."}]", "excerpt_truncated": true, "source_sha256": "a05a0ce8798b9e0bac80d729c51690685848a8fba8028d0697b014559c563620", "verification_required": true, "topic_domain": "unrecognized_reasoning_limits", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1162/coli_a_00478", "doi:10.1162/coli_a_00478/2131576/coli_a_00478.pdf", "openalex:W4367599042"], "source_candidates": ["https://doi.org/10.1162/coli_a_00478", "https://direct.mit.edu/coli/article-pdf/doi/10.1162/coli_a_00478/2131576/coli_a_00478.pdf"], "source_candidate_identities": {}}
